class Solution {
    public String reverseWords(String s){
        char[] chars=s.toCharArray();
        for(int start=0,end=0;end<=chars.length;end++)if(end==chars.length||chars[end]==' '){
            for(int left=start,right=end-1;left<right;left++,right--){
                char value=chars[left];
                chars[left]=chars[right];
                chars[right]=value;
            }
            start=end+1;
        }
        return new String(chars);
    }
}

code.kotlin:
class Solution {
    fun reverseWords(s:String):String{
        val chars=s.toCharArray();
        var start=0;
        var end=0;
        while(end<=chars.size){
            if(end==chars.size||chars[end]==' '){
                var left=start;
                var right=end-1;
                while(left<right){
                    val value=chars[left];
                    chars[left++]=chars[right];
                    chars[right--]=value
                };
                start=end+1
            };
            end++
        };
        return String(chars)
    }
}

